def plan_for(document_hash,cik):
    review=REVIEWED.get(document_hash)
    if review is None or str(int(cik)).zfill(10)!=review['cik']:return None
    facts=[]
    for table,spec in review['tables'].items():
        for row,tag,label,start,end,unit,decimals,value,columns in spec['facts']:
            facts.append(dict(concept='{http://fasb.org/us-gaap/2021}'+tag,period_start=start,period_end=end,
                unit=unit,scale=0,decimals=decimals,expected_value=value,label=label,evidence=review['evidence'],
                table_proof=dict(heading=spec['heading'],headers=spec['headers']),
                locator=dict(kind='cells',table=table,row=row,label_column=0,columns=columns)))
    body=dict(version=VERSION,document_hash=document_hash,cik=review['cik'],scope='reviewed_observations',facts=facts)
    return dict(body,plan_hash=digest(body))
